sksl:
uniform shader image;
uniform float2 size;
uniform float4 screen;
uniform float time;
uniform float count;
uniform float angle;
uniform float phase;
uniform float maskToLayer;
uniform float alpha;
half4 main(float2 coord) {
    half4 own = image.eval(coord);
    if (count <= 0.0) return half4(0.0);
    float a = radians(angle);
    float2 along = float2(cos(a), sin(a));
    float2 across = float2(-sin(a), cos(a));
    float2 d = coord / size - 0.5;
    float h = 1.0 / count;
    float shift = phase * 0.1 * h;
    float v = dot(d, across) + 0.5 - shift;
    float edge = (floor(v / h) + 1.0) * h - 0.5 + shift;
    float2 p = (0.5 + along * dot(d, along) + across * edge) * size;
    half4 strip = image.eval(clamp(p, screen.xy + 0.5, screen.xy + screen.zw - 0.5));
    half4 r = maskToLayer > 0.5 ? (strip + own * (1.0 - strip.a)) * own.a : strip;
    return mix(own, r, half(clamp(alpha, 0.0, 1.0)));
}
